public class PermuteAll {
    public List<List<Integer>> permute(int[] nums) {
        // Initialize the result list to hold the permutations
        List<List<Integer>> result = new ArrayList<>();
        // Helper function to rotate subarray from start to end
        void rotate(int[] arr, int start, int end) {
            while (start < end) {
                int temp = arr[start];
                arr[start] = arr[end];
                arr[end] = temp;
                start++;
                end--;
            }
        }

        // Backtracking function to find all permutations
        void backtrack(int[] nums, int start) {
            // If all elements are placed in the current permutation, add it to result
            if (start == nums.length) {
                result.add(new ArrayList<>(Arrays.asList(nums)));
                return;
            }

            for (int i = start; i < nums.length; i++) {
                // If the current element is not placed in the permutation yet
                if (!visited[i]) {
                    // Place the current element in the permutation
                    visited[i] = true;
                    nums[start] = nums[i];
                    // Recur for the the rest of the elements
                    backtrack(nums, start + 1);
                    // backtrack to remove the current element
                    visited[i] = false;
                    nums[start] = i + 1;
                }
            }
        }

        // Array of visited elements to keep track of which elements are already placed
        boolean[] visited = new boolean[nums.length];

        // Start the backtracking process
        backtrack(nums, 0);

        return result;
    }
