 public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) {
        return 1;
    }
    if (n % 2 != 0) {
        return 0;
    }
    int count = 0;
    int validCount = 0;
    boolean[] visited = new boolean[n];
    int[] temp = new int[n / 2];

    for (int i = 0; i < n / 2; i++) {
        temp[i] = A[i];
    }

    for (int i = 0; i < n / 2; i++) {
        if (visited[i] || (temp[i] < 0)) {
            continue;
        }
        visited[i] = true;
        for (int j = i + 1; j < n / 2; j++) {
            if (visited[j] || (temp[j] < 0)) {
                continue;
            }
            visited[j] = true;
            int num1 = temp[i] * temp[i];
            int num2 = temp[j] * temp[j];
            if (!isSquare(num1 + num2)) {
                visited[j] = false;
            } else {
                swap(temp, i, j);
                validCount++;
                count += squarePermutations(temp);
                swap(temp, i, j);
                visited[j] = false;
            }
            visited[j] = false;
        }
        visited[i] = false;
    }

    return count;
}

private static boolean isSquare(int num) {
    int root = (int) Math.sqrt(num);
    return root * root == num;
}

private static void swap(int[] arr, int i, int j) {
    int temp = arr[i];
    arr[i] = arr[j];
    arr[j] = temp;
}
