public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        throw new IllegalArgumentException("Height array cannot be null or empty");
    }

    int[] leftSmaller = new int[heights.length];
    int[] rightSmaller = new int[heights.length];
    leftSmaller[0] = -1; // Starting from the left, find the nearest smaller element to the left for the first bar
    rightSmaller[heights.length - 1] = heights.length; // Starting from the right, find the nearest smaller element to the right for the last bar

    for (int i = 1; i < heights.length; i++) {
        int j = i - 1;
        while (j >= 0 && heights[j] >= heights[i]) {
            j = leftSmaller[j]; // Move the pointer to the left until a smaller element is found
        }
        leftSmaller[i] = j; // Store the index of the nearest smaller element
    }

    for (int i = heights.length - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < heights.length && heights[j] >= heights[i]) {
            j = rightSmaller[j]; // Move the pointer to the right until a smaller element is found
        }
        rightSmaller[i] = j; // Store the index of the nearest smaller element
    }

    int maxArea = 0;
    for (int i = 0; i < heights.length; i++) {
        int width = rightSmaller[i] - leftSmaller[i] - 1;
        int area = heights[i] * width;
        maxArea = Math.max(maxArea, area); // Update the maximum area if the current area is larger
    }

    return maxArea;
}
