        int i = left + (leftToRight ? 1 : -1);
        int j = up + (leftToRight ? 0 : 1);

        while (i < m && j < n) {
            result.add(mat[i][j]);
            i += leftToRight ? 1 : -1;
            j += leftToRight ? 0 : 1;
