        leftToRight = !leftToRight;
        if (leftToRight) {
            left = left + m > 0 ? left + 1 : 0;
            if (left == 0 && ---up < 0) {
                break;
            }
        } else {
            up = up + n > 0 ? up + 1 : 0;
            if (up == 0 && ---left < 0) {
