public static boolean isBoomerang(int[][] points) {
    if (points.length != 3) {
        return false;
    }

    int x1 = points[0][0];
    int y1 = points[0][1];
    int x2 = points[1][0];
    int y2 = points[1][1];
    int x3 = points[2][0];
    int y3 = points[2][1];

