    int s = (x2 - x1) * (y3 - y2) + (x3 - x2) * (y1 - y3);
    double area = s > 0 ? 0.5 * s : -0.5 * s;

    // Conversely, the area can also be expressed as half the cross-product of vectors AB and AC
    double crossProduct = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);

